	@Test
	void concurrentCloseWaitsForTheFirstCompleteCleanup() throws Exception {
		CountDownLatch valueCloseEntered = new CountDownLatch(1);
		CountDownLatch releaseValueClose = new CountDownLatch(1);
		AtomicBoolean first = new AtomicBoolean(true);
		AtomicInteger valueNativeCloses = new AtomicInteger();
		LmdbSailStore owner = directOwner((root, properties, selected) -> new ValueStore(root, properties, selected) {
			@Override
			public void close() throws IOException {
				if (first.getAndSet(false)) {
					valueCloseEntered.countDown();
					await(releaseValueClose);
				}
				super.close();
			}

			@Override
			void closeEnvironment(long environment) {
				valueNativeCloses.incrementAndGet();
				super.closeEnvironment(environment);
			}
		});
		AtomicReference<Throwable> firstFailure = new AtomicReference<>();
		AtomicReference<Throwable> secondFailure = new AtomicReference<>();
		CountDownLatch secondFinished = new CountDownLatch(1);
		Thread firstCloser = closer(owner, firstFailure, null);
		Thread secondCloser = closer(owner, secondFailure, secondFinished);
		Throwable failure = null;
		firstCloser.start();
		try {
			valueCloseEntered.await();
			secondCloser.start();
			awaitBlockedOrFinished(secondCloser);
			assertEquals(1L, secondFinished.getCount(),
					"closing admission cannot let a second close return before the first cleanup finishes");
		} catch (Throwable caught) {
			failure = caught;
		} finally {
			releaseValueClose.countDown();
			failure = run(failure, firstCloser::join);
			if (secondCloser.getState() != Thread.State.NEW) {
				failure = run(failure, secondCloser::join);
			}
		}
		failure = run(failure, () -> assertNull(firstFailure.get()));
		failure = run(failure, () -> assertNull(secondFailure.get(),
				"a concurrent caller joins completion instead of reentering closed native state"));
		failure = run(failure, () -> assertEquals(1, valueNativeCloses.get()));
		failure = finishOwner(failure, owner);
		rethrow(failure);
	}

	@Test
	void recursiveShutdownOwnerIsRefusedBeforeStartingAnotherCleanupPass() throws Exception {
		AtomicReference<LmdbSailStore> owner = new AtomicReference<>();
		AtomicBoolean firstPersist = new AtomicBoolean(true);
		AtomicInteger refusals = new AtomicInteger();
		var config = config();
		config.setExperimentalQueryOptimizations(true);
		LmdbSailStore backing = new LmdbSailStore(directory.toFile(), new StoreProperties(directory.toFile()),
				config, true, ValueStore::new, TripleStore::new, PersistentSetFactory::new,
				(path, triples, values, sampling, millis, rows, background) -> new LmdbFilterSelectivityStats(path,
						triples, values, sampling, millis, rows, background) {
					@Override
					synchronized void persistIfDirty() {
						if (owner.get() != null && firstPersist.getAndSet(false)) {
							assertThrows(SailException.class, owner.get()::close,
									"the active cleanup owner must not recursively start another close pass");
							refusals.incrementAndGet();
						}
						super.persistIfDirty();
					}
				});
		owner.set(backing);
		Throwable failure = null;
		try {
			assertDoesNotThrow(backing::close);
			assertEquals(1, refusals.get());
			assertFalse(backing.valueStore().isNativeEnvironmentOpen());
			assertFalse(backing.getTripleStore().isNativeEnvironmentOpen());
		} catch (Throwable caught) {
			failure = caught;
		} finally {
			failure = finishOwner(failure, backing);
		}
		rethrow(failure);
	}

	@Test
	void activePublicationOwnerIsRefusedBeforeWaitingForAnotherCloser() throws Exception {
		LmdbSailStore owner = directOwner(null);
		AtomicReference<Throwable> closeFailure = new AtomicReference<>();
		Thread closer = closer(owner, closeFailure, null);
		var publication = owner.beginPublication(new Object());
		Throwable failure = null;
		try {
			closer.start();
			awaitBlockedOrFinished(closer);
			SailException refusal = assertThrows(SailException.class, owner::close,
					"the live publication owner must be refused before joining the closer waiting for it");
			assertEquals("An active LMDB native/publication owner cannot close its own store", refusal.getMessage());
		} catch (Throwable caught) {
			failure = caught;
		} finally {
			failure = run(failure, publication::close);
			failure = run(failure, closer::join);
		}
		failure = run(failure, () -> assertNull(closeFailure.get()));
		failure = finishOwner(failure, owner);
		rethrow(failure);
	}

	private LmdbSailStore directOwner(LmdbSailStore.ValueStoreFactory values) throws IOException {
		var config = config();
		StoreProperties properties = new StoreProperties(directory.toFile());
		LmdbStoreFormat.forNewStore(config).initializeProperties(properties);
		properties.getOrCreateStoreId();
		properties.save();
		return new LmdbSailStore(directory.toFile(), properties, config, false, values, TripleStore::new);
	}

	private LmdbStore store(LmdbStoreConfig config, LmdbSailStore.ValueStoreFactory values,
			LmdbSailStore.TripleStoreFactory triples) {
		return new LmdbStore(directory.toFile(), config) {
			@Override
			LmdbSailStore createBackingStore(File root, StoreProperties properties, LmdbStoreConfig selected,
					boolean sketch) throws IOException {
				return new LmdbSailStore(root, properties, selected, false, values, triples);
			}
		};
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setForceSync(true)
				.setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setBackgroundRawSamplingEnabled(false)
				.setBackgroundRawSamplingMaxMillisPerCycle(0L);
	}

	@FunctionalInterface
	private interface Action {
		void run() throws Exception;
	}

	private static Throwable run(Throwable primary, Action action) {
		try {
			action.run();
		} catch (Throwable cleanup) {
			if (primary == null) {
				return cleanup;
			}
			if (primary != cleanup) {
				primary.addSuppressed(cleanup);
			}
		}
		return primary;
	}

	private static Throwable finishOwner(Throwable primary, LmdbSailStore owner) {
		// Disarmed callers first retry the actual outer owner, so auxiliaries receive their ordinary close attempts.
		primary = run(primary, owner::close);
		// The authentic preimage can abort that retry before child close. Finish only any real remaining native owners.
		ValueStore values = owner.valueStore();
		if (values != null && values.isNativeEnvironmentOpen()) {
			primary = run(primary, values::close);
		}
		TripleStore triples = owner.getTripleStore();
		if (triples != null && triples.isNativeEnvironmentOpen()) {
			primary = run(primary, triples::close);
		}
		return primary;
	}

	private static void rethrow(Throwable failure) throws Exception {
		if (failure instanceof Exception exception) {
			throw exception;
		}
		if (failure instanceof Error error) {
			throw error;
		}
		if (failure != null) {
			throw new AssertionError(failure);
		}
	}

	private static Thread closer(LmdbSailStore owner, AtomicReference<Throwable> failure, CountDownLatch finished) {
		return new Thread(() -> {
			try {
				owner.close();
			} catch (Throwable caught) {
				failure.set(caught);
			} finally {
				if (finished != null) {
					finished.countDown();
				}
			}
		}, "lmdb-close-lifecycle-caller");
	}

	private static void await(CountDownLatch latch) throws IOException {
		try {
			latch.await();
		} catch (InterruptedException interruption) {
			Thread.currentThread().interrupt();
			throw new IOException("interrupted in the controlled value close rendezvous", interruption);
		}
	}

	private static void awaitBlockedOrFinished(Thread thread) {
		// No guessed wait interval: this caller executes only close(). Observe its actual block or completion.
		while (thread.isAlive()) {
			Thread.State state = thread.getState();
			if (state == Thread.State.BLOCKED || state == Thread.State.WAITING || state == Thread.State.TIMED_WAITING) {
				return;
			}
			Thread.yield();
		}
	}
